void mergesort(int a[], int l, int r) {
    if (l >= r) return;
    int mid = l + r >> 1, i = l, j = mid + 1, k = 0;
    mergesort(a, l, mid); mergesort(a, mid + 1, r);
    // 谁小谁先进临时数组，再把剩下的收尾
    while (i <= mid && j <= r) tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= r) tmp[k++] = a[j++];
    for (i = l; i <= r; i++) a[i] = tmp[i - l];
}

ll mergeSort(vector<int>& a, int l, int r) {
    if (l >= r) return 0;
    int mid = (l + r) / 2;
    ll cnt = mergeSort(a, l, mid) + mergeSort(a, mid + 1, r);
    // 右边元素小于左边时，左边剩下 mid-i+1 个元素都是逆序
    int i = l, j = mid + 1, k = 0;
    while (i <= mid && j <= r)
        a[i] <= a[j] ? tmp[k++] = a[i++] : (tmp[k++] = a[j++], cnt += mid - i + 1);
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= r) tmp[k++] = a[j++];
    for (i = l; i <= r; i++) a[i] = tmp[i - l];
    return cnt;
}

