    if(dist[n]==0x3f3f3f3f) return -1;
    return dist[n];
}

// 0-1 BFS：匹配当前斜线cost=0放队首，不匹配cost=1放队尾
int cost=(g[gx][gy]==wire[d])?0:1;
if(dist[x][y]+cost<dist[nx][ny]){
    dist[nx][ny]=dist[x][y]+cost;
    if(cost==0) dq.push_front({nx,ny});
    else dq.push_back({nx,ny});
}
// wire[d]对应4个方向的期望斜线方向
const char wire[4]={'\\','/','/','\\'};

if(!d[i]) q[++tt]=i;          // 所有入度为0的点先入队
while(hh<=tt){
    int t=q[hh++];
    for(int i=head[t];~i;i=nextVertex[i])
        if(--d[edge[i]]==0) q[++tt]=edge[i];
}

if(f<C && c+price[u] < dist[u][f+1])          // 加1单位油
    dist[u][f+1]=c+price[u], pq.push({u,f+1,c+price[u]});
for(auto &e: g[u])
    if(f>=e.d && c < dist[e.to][f-e.d])        // 沿边走，消耗e.d油
        dist[e.to][f-e.d]=c, pq.push({e.to,f-e.d,c});

for(int i=n-1;i;i--)
    for(int j=1;j<=i;j++)
        f[i][j]+=max(f[i+1][j],f[i+1][j+1]);   // 从下往上，选大的累加

for(int i=1;i<=n;i++)
    for(int j=0;j<=m;j++){
        f[i][j]=f[i-1][j];
        if(j>=v[i]) f[i][j]=max(f[i][j],f[i-1][j-v[i]]+w[i]);  // 选第i件
    }

for(int i=1;i<=n;i++)
    for(int j=0;j<=m;j++){
        f[i][j]=f[i-1][j];
        if(j>=v[i]) f[i][j]=max(f[i][j],f[i][j-v[i]]+w[i]);    // 完全背包：同层可以重复选
    }

for(int i=1;i<=n;i++)
    for(int j=0;j<=m;j++)
        for(int k=0;k<=s[i];k++)
            if(j>=v[i]*k) f[i][j]=max(f[i][j],f[i-1][j-k*v[i]]+k*w[i]);  // 枚举选k件

int k=1;
while(k<=s){
    v[++cnt]=a*k; w[cnt]=b*k;    // 拆成二进制组
    s-=k; k*=2;
}
if(s>0) v[++cnt]=a*s, w[cnt]=b*s;  // 余数单独成组

for(int i=1;i<=n;i++)
    for(int j=m;j>=1;j--)           // 容量倒序，保证每组最多选一个
        for(int k=1;k<=s[i];k++)
            if(v[i][k]<=j) f[j]=max(f[j],f[j-v[i][k]]+w[i][k]);

if(!s) for(int j=v;j<=m;j++) f[j]=max(f[j],f[j-v]+w);   // 完全背包：正序
else{
    if(s==-1) s=1;  // 01背包当si=1的多重背包
    // 二进制拆包后跑01背包（倒序）
    for(int k=1;k<=s;k*=2){ ... }
    if(s) { ... }
}

for(int i=1;i<=n;i++)
    for(int j=1;j<=m;j++)
        f[i][j]=max(f[i-1][j],f[i][j-1])+w[i][j];   // 从上方或左方转移

for(int i=1;i<=n;i++)
    for(int j=1;j<=n;j++)
        if(i==1&&j==1) f[i][j]=w[i][j];
        else {
            f[i][j]=INF;
            // 2N-1限制意味着不能绕路，只考虑从上方和左方转移
            if(i>1) f[i][j]=min(f[i][j],f[i-1][j]+w[i][j]);
            if(j>1) f[i][j]=min(f[i][j],f[i][j-1]+w[i][j]);
        }

for(int i=1;i<=n;i++) {
    f[i]=1;
    for(int j=1;j<i;j++)
        if(a[j]<a[i])  // a[i]能接在以a[j]结尾的序列后面
            f[i]=max(f[i],f[j]+1);
}

int len=0;
for(int i=0;i<n;i++) {
    int l=0,r=len;
    while(l<r) {
        int mid=l+r+1>>1;
        if(q[mid]<a[i]) l=mid;
        else r=mid-1;
    }
    // q[r+1]=a[i] 更新长度为r+1的上升子序列的最小末尾
    len=max(len,r+1), q[r+1]=a[i];
}

for(int i=0;i<n;i++) {
    f[i]=1;
    for(int j=0;j<i;j++)
        if(h[i]<=h[j]) f[i]=max(f[i],f[j]+1);
    res=max(res,f[i]);
    // 贪心分配系统：找第一个高度>=h[i]的系统，没有就新建一套
    int k=0;
    while(k<cnt&&q[k]<h[i]) k++;
    if(k==cnt) q[cnt++]=h[i];
    else q[k]=h[i];
}

for(int i=1;i<=n;i++)
    for(int j=1;j<=m;j++)
        if(a[i]==b[j])
            f[i][j]=f[i-1][j-1]+1;  // 匹配上了，长度加1
        else
            f[i][j]=max(f[i-1][j],f[i][j-1]);  // 没匹配上，继承两边的较大值

for(int len=2;len<=n;len++)
    for(int i=1;i+len-1<=n;i++) {
        int j=i+len-1;
        for(int k=i;k<j;k++)
            // 枚举分割点，左右分别合并后再合并，加上区间总和
            f[i][j]=min(f[i][j],f[i][k]+f[k+1][j]+s[j]-s[i-1]);
    }

for(int k=l;k<=r;k++) {
    int left = (k==l ? 1 : f[l][k-1]);   // 左子树为空时加分定义为1
    int right = (k==r ? 1 : f[k+1][r]);  // 右子树为空时加分也定义为1
    int score = left * right + w[k];
    if(score > f[l][r]) f[l][r]=score, root[l][r]=k;
}

void dfs(int u) {
    f[u][1] = happy[u];
    for(int v : g[u]) {
        dfs(v);
        f[u][0] += max(f[v][0], f[v][1]);  // u不去，下属可以去也可以不去
        f[u][1] += f[v][0];                 // u去了，下属都不能去
    }
}
